#[test]
fn read_toc_fixture() {
    let Some(dir) = fixture_dir("multi_partition") else {
        eprintln!("Skipping: TOC fixture not generated");
        return;
    };

    let toc_bytes = load_component(&dir, "TOC.txt");
    let entries = toc::read_toc(&toc_bytes).unwrap();
    assert!(entries.len() >= 6, "TOC should list at least 6 components");
}

#[test]
fn read_statistics_fixture() {
    let Some(dir) = fixture_dir("multi_partition") else {
        eprintln!("Skipping: Statistics fixture not generated");
        return;
    };

    let stats_bytes = load_component(&dir, "Statistics.db");
    let stats = read_statistics(&stats_bytes).unwrap();

    assert_eq!(
        stats.validation.partitioner_class,
        "org.apache.cassandra.dht.Murmur3Partitioner"
    );
    assert!(
        stats.validation.bloom_fp_chance > 0.0 && stats.validation.bloom_fp_chance < 1.0,
        "bloom FP chance should be between 0 and 1"
    );

    // Header should have column definitions matching our schema
    assert_eq!(
        stats.header.clustering_types.len(),
        1,
        "1 clustering column (ck int)"
    );
    assert_eq!(
        stats.header.regular_columns.len(),
        1,
        "1 regular column (val text)"
    );
}

#[test]
/// Write-read roundtrip: ferrosa writer produces SSTables that ferrosa reader
/// can parse, for all cell types (normal, tombstone, expiring/TTL).
/// This validates the wire format matches Cassandra's Cell.Serializer spec.
fn ferrosa_write_read_roundtrip_all_cell_types() {
    use ferrosa_common::CellValue;
    use ferrosa_sstable::data::DataReader;
    use ferrosa_sstable::statistics::SerializationHeader;
    use ferrosa_sstable::types::*;
    use ferrosa_sstable::writer::{SSTableWriter, WriteOptions};

    let header = SerializationHeader {
        min_timestamp: 1_000_000,
        min_local_deletion_time: 0,
        min_ttl: 0,
        key_type: "org.apache.cassandra.db.marshal.UTF8Type".into(),
        clustering_types: vec!["org.apache.cassandra.db.marshal.Int32Type".into()],
        static_columns: vec![],
        regular_columns: vec![(
            b"val".to_vec(),
            "org.apache.cassandra.db.marshal.UTF8Type".into(),
        )],
    };
    let options = WriteOptions {
        compression: None,
        bloom_fp_chance: 0.01,
        chunk_size: 65536,
    };

    let timestamp = 1_000_100i64;

    // Three partitions: normal cell, tombstone cell, expiring cell (TTL)
    let partitions = vec![
        // 1. Normal cell
        Partition {
            key: DecoratedKey::new(PartitionKey::from(b"normal".as_slice())),
            deletion: DeletionTime::LIVE,
            static_row: None,
            rows: vec![Row {
                clustering: vec![0, 0, 0, 1], // ck = 1
                cells: vec![(0, CellValue::live(b"hello".to_vec(), timestamp))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(timestamp),
            }],
        },
        // 2. Tombstone cell
        Partition {
            key: DecoratedKey::new(PartitionKey::from(b"tombstone".as_slice())),
            deletion: DeletionTime::LIVE,
            static_row: None,
            rows: vec![Row {
                clustering: vec![0, 0, 0, 2],
                cells: vec![(0, CellValue::tombstone(timestamp, 1_700_000))],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(timestamp),
            }],
        },
        // 3. Expiring cell (USING TTL 3600)
        Partition {
            key: DecoratedKey::new(PartitionKey::from(b"ttl_cell".as_slice())),
            deletion: DeletionTime::LIVE,
            static_row: None,
            rows: vec![Row {
                clustering: vec![0, 0, 0, 3],
                cells: vec![(
                    0,
                    CellValue::expiring(b"expires".to_vec(), timestamp, 3600, 1_700_000),
                )],
                deletion: DeletionTime::LIVE,
                primary_key_liveness: LivenessInfo::with_timestamp(timestamp),
            }],
        },
    ];

    let mut writer = SSTableWriter::new(options, header.clone());
    for p in &partitions {
        writer.add_partition(p).unwrap();
    }
    let output = writer.finish().unwrap();

    // Read back and verify each partition
    let mut reader = DataReader::new(&output.data, &header, 0);

    // 1. Normal cell
    let p = reader.read_partition().unwrap().expect("normal partition");
    assert_eq!(p.key.key.as_bytes(), b"normal");
    let cell = &p.rows[0].cells[0].1;
    assert!(!cell.is_tombstone());
    assert_eq!(
        cell.ttl,
        ferrosa_common::NO_TTL,
        "normal cell should have no TTL"
    );
    assert_eq!(cell.value.as_deref(), Some(b"hello".as_slice()));

    // 2. Tombstone cell
    let p = reader
        .read_partition()
        .unwrap()
        .expect("tombstone partition");
    assert_eq!(p.key.key.as_bytes(), b"tombstone");
    let cell = &p.rows[0].cells[0].1;
    assert!(cell.is_tombstone());
    assert_eq!(cell.timestamp, timestamp);
    assert_eq!(cell.local_deletion_time, 1_700_000);
    assert!(cell.value.is_none());

    // 3. Expiring cell
    let p = reader.read_partition().unwrap().expect("ttl partition");
    assert_eq!(p.key.key.as_bytes(), b"ttl_cell");
    let cell = &p.rows[0].cells[0].1;
    assert!(!cell.is_tombstone(), "expiring cell is not a tombstone");
    assert_eq!(cell.ttl, 3600, "TTL must survive roundtrip");
    assert_eq!(
        cell.local_deletion_time, 1_700_000,
        "LDT must survive roundtrip"
    );
    assert_eq!(cell.value.as_deref(), Some(b"expires".as_slice()));

    // No more partitions
    assert!(reader.read_partition().unwrap().is_none());
}

#[test]
/// The compat test infrastructure files must exist before a Docker run is
/// attempted.  This test acts as a quick smoke-check: if the files are
/// missing the CI step that calls `compat_test.sh` would fail with a
/// confusing error.
fn cassandra_reader_container_starts() {
    // docker-compose.yml
    assert!(
        std::path::Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../tests/sstable-compat/docker-compose.yml"
        ))
        .exists(),
        "tests/sstable-compat/docker-compose.yml must exist"
    );

    // compat_test.sh
    assert!(
        std::path::Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../tests/sstable-compat/compat_test.sh"
        ))
        .exists(),
        "tests/sstable-compat/compat_test.sh must exist"
    );

    // write-sstable Cargo.toml
    assert!(
        std::path::Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../tests/sstable-compat/Cargo.toml"
        ))
        .exists(),
        "tests/sstable-compat/Cargo.toml must exist"
    );

    // write_sstable.rs binary source
    assert!(
        std::path::Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../tests/sstable-compat/src/write_sstable.rs"
        ))
        .exists(),
        "tests/sstable-compat/src/write_sstable.rs must exist"
    );
}

#[test]
/// Rust-side round-trip for all simple CQL types through SSTableWriter +
/// DataReader.  This validates the on-disk encoding without Docker.  The
/// Cassandra-side import is handled by `compat_test.sh`.
///
/// Schema:
///   compat.simple_types (id int PRIMARY KEY, v_text text, v_bool boolean,
///     v_bigint bigint, v_float float, v_double double, v_blob blob)
fn sstable_compat_simple_types() {
    use ferrosa_common::CellValue;
    use ferrosa_sstable::data::DataReader;
    use ferrosa_sstable::statistics::SerializationHeader;
    use ferrosa_sstable::types::{DeletionTime, LivenessInfo, Row};
    use ferrosa_sstable::writer::{SSTableWriter, WriteOptions};

    // Column index -> type mapping (same ordering used in write_sstable.rs):
    //   0 v_text   UTF8Type
    //   1 v_bool   BooleanType
    //   2 v_bigint LongType
    //   3 v_float  FloatType
    //   4 v_double DoubleType
    //   5 v_blob   BytesType
    let header = SerializationHeader {
        min_timestamp: 1_000_000,
        min_local_deletion_time: i32::MAX,
        min_ttl: 0,
        key_type: "org.apache.cassandra.db.marshal.Int32Type".into(),
        clustering_types: vec![],
        static_columns: vec![],
        regular_columns: vec![
            (
                b"v_text".to_vec(),
                "org.apache.cassandra.db.marshal.UTF8Type".into(),
            ),
            (
                b"v_bool".to_vec(),
                "org.apache.cassandra.db.marshal.BooleanType".into(),
            ),
            (
                b"v_bigint".to_vec(),
                "org.apache.cassandra.db.marshal.LongType".into(),
            ),
            (
                b"v_float".to_vec(),
                "org.apache.cassandra.db.marshal.FloatType".into(),
            ),
            (
                b"v_double".to_vec(),
                "org.apache.cassandra.db.marshal.DoubleType".into(),
            ),
            (
                b"v_blob".to_vec(),
                "org.apache.cassandra.db.marshal.BytesType".into(),
            ),
        ],
    };
    let options = WriteOptions {
        compression: None,
        bloom_fp_chance: 0.01,
        chunk_size: 65536,
    };

    let ts = 1_743_120_000_000_000i64;

    // Partition key: id = 1 encoded as big-endian i32.
    let pk_bytes: [u8; 4] = 1i32.to_be_bytes();
    let partition = ferrosa_sstable::types::Partition {
        key: ferrosa_common::DecoratedKey::new(ferrosa_common::PartitionKey::from(
            pk_bytes.as_slice(),
        )),
        deletion: DeletionTime::LIVE,
        static_row: None,
        rows: vec![Row {
            clustering: vec![],
            cells: vec![
                (0, CellValue::live(b"hello".to_vec(), ts)),
                (1, CellValue::live(vec![0x01], ts)),          // boolean true
                (2, CellValue::live(42i64.to_be_bytes().to_vec(), ts)),
                (3, CellValue::live((3.14f32).to_bits().to_be_bytes().to_vec(), ts)),
                (4, CellValue::live((2.718_281_828f64).to_bits().to_be_bytes().to_vec(), ts)),
                (5, CellValue::live(vec![0xDE, 0xAD, 0xBE, 0xEF], ts)),
            ],
            deletion: DeletionTime::LIVE,
            primary_key_liveness: LivenessInfo::with_timestamp(ts),
        }],
    };

    let mut writer = SSTableWriter::new(options, header.clone());
    writer.add_partition(&partition).unwrap();
    let output = writer.finish().unwrap();

    // Read back with DataReader and verify every cell.
    let mut reader = DataReader::new(&output.data, &header, 0);
    let p = reader
        .read_partition()
        .unwrap()
        .expect("expected one partition");

    assert_eq!(p.key.key.as_bytes(), pk_bytes.as_slice(), "partition key");
    assert!(p.deletion.is_live(), "partition deletion must be live");
    assert_eq!(p.rows.len(), 1, "one row");

    let row = &p.rows[0];
    assert!(row.clustering.is_empty(), "no clustering columns");
    assert_eq!(row.primary_key_liveness.timestamp, ts);
    assert_eq!(row.cells.len(), 6, "six regular columns");

    // col 0: v_text = "hello"
    let (idx, ref cell) = row.cells[0];
    assert_eq!(idx, 0);
    assert!(cell.is_live());
    assert_eq!(cell.value.as_deref(), Some(b"hello".as_slice()), "v_text");

    // col 1: v_bool = 0x01 (true)
    let (idx, ref cell) = row.cells[1];
    assert_eq!(idx, 1);
    assert_eq!(cell.value.as_deref(), Some([0x01].as_slice()), "v_bool");

    // col 2: v_bigint = 42
    let (idx, ref cell) = row.cells[2];
    assert_eq!(idx, 2);
    let bigint_bytes = cell.value.as_deref().expect("v_bigint value");
    assert_eq!(
        i64::from_be_bytes(bigint_bytes.try_into().unwrap()),
        42i64,
        "v_bigint"
    );

    // col 3: v_float = 3.14
    let (idx, ref cell) = row.cells[3];
    assert_eq!(idx, 3);
    let float_bytes = cell.value.as_deref().expect("v_float value");
    let float_bits = u32::from_be_bytes(float_bytes.try_into().unwrap());
    assert!(
        (f32::from_bits(float_bits) - 3.14f32).abs() < 1e-5,
        "v_float should be ~3.14, got {}",
        f32::from_bits(float_bits)
    );

    // col 4: v_double = 2.718281828
    let (idx, ref cell) = row.cells[4];
    assert_eq!(idx, 4);
    let double_bytes = cell.value.as_deref().expect("v_double value");
    let double_bits = u64::from_be_bytes(double_bytes.try_into().unwrap());
    assert!(
        (f64::from_bits(double_bits) - 2.718_281_828f64).abs() < 1e-9,
        "v_double should be ~2.718281828, got {}",
        f64::from_bits(double_bits)
    );

    // col 5: v_blob = 0xDEADBEEF
    let (idx, ref cell) = row.cells[5];
    assert_eq!(idx, 5);
    assert_eq!(
        cell.value.as_deref(),
        Some([0xDE, 0xAD, 0xBE, 0xEF].as_slice()),
        "v_blob"
    );

    // No more partitions.
    assert!(reader.read_partition().unwrap().is_none());
}

#[test]
/// Read SSTable fixtures generated by Cassandra's CQLSSTableWriter.
/// These test that ferrosa can read SSTables produced by real Cassandra code.
/// Run `tests/sstable-compat/generate.sh` to create the fixtures.
fn read_cassandra_generated_normal_cells() {
    let Some(dir) = fixture_dir("cassandra_generated/normal_cells") else {
        eprintln!(
            "Skipping: Cassandra-generated fixtures not found. Run tests/sstable-compat/generate.sh"
        );
        return;
    };

    // Find the actual SSTable directory (Cassandra puts them in a subdirectory)
    let sstable_dirs: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().is_dir())
        .collect();

    if sstable_dirs.is_empty() {
        // Files might be directly in the directory
        let reader = open_fixture(&dir);
        assert!(
            reader.key_count() >= 3,
            "expected at least 3 partitions (alpha, bravo, charlie)"
        );
    } else {
        // Cassandra nests SSTables in subdirectories
        for sub in sstable_dirs {
            let path = sub.path();
            if std::fs::read_dir(&path).unwrap().any(|e| {
                e.unwrap()
                    .file_name()
                    .to_string_lossy()
                    .ends_with("-Data.db")
            }) {
                eprintln!("Reading Cassandra SSTable from {:?}", path);
                // TODO: Cassandra uses different file naming (e.g., nb-1-big-Data.db)
                // Need to adapt the reader for Cassandra's file naming convention
            }
        }
    }
}

